// Crea el estado único de SIMCVI en el contexto global (una sola vez).
const nucleo = global.get('simcvi');
if (!nucleo) {
    node.error('No se cargó el núcleo SIMCVI: revise functionGlobalContext en settings.js.');
    node.status({ fill: 'red', shape: 'ring', text: 'sin núcleo' });
    return null;
}
if (!global.get('estado')) {
    global.set('estado', nucleo.crearEstado());
    node.log(`Estado SIMCVI ${nucleo.VERSION} creado.`);
}
node.status({ fill: 'green', shape: 'dot', text: `núcleo ${nucleo.VERSION}` });
return null;

// Ejecuta un ciclo del núcleo cuando corresponde según el intervalo configurado.
const nucleo = global.get('simcvi');
const estado = global.get('estado');
if (!nucleo || !estado) return null;

const resultado = nucleo.ciclo(estado, Date.now());
if (!resultado) return null;

const k = resultado.instantanea.kpis;
node.status({
    fill: k.emergencia ? 'red' : (k.zonasAlerta ? 'yellow' : 'green'),
    shape: 'dot',
    text: `ciclo ${estado.simulacion.ciclos} · alerta ${k.zonasAlerta}/${k.zonas}`,
});
// Salida 1: instantánea para la interfaz. Salida 2: líneas para InfluxDB.
return [{ payload: resultado.instantanea }, { payload: resultado.lineas }];

// Delegar la solicitud al núcleo; aquí solo se adapta Node-RED ↔ HTTP.
const nucleo = global.get('simcvi');
const estado = global.get('estado');
msg.headers = {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
};
if (!nucleo || !estado) {
    msg.statusCode = 503;
    msg.payload = { ok: false, error: { codigo: 503, mensaje: 'SIMCVI se está iniciando. Intente de nuevo.' } };
    return [msg, null, null];
}

const solicitud = { metodo: msg.req.method, ruta: msg.req.path, cuerpo: msg.payload };
const respuesta = nucleo.atenderSolicitud(estado, solicitud, Date.now());
msg.statusCode = respuesta.estado;
msg.payload = respuesta.cuerpo;

const difusion = respuesta.difundir ? { payload: nucleo.instantanea(estado) } : null;
const lineas = respuesta.persistir ? nucleo.lineasEventosPendientes(estado) : [];
return [msg, difusion, lineas.length ? { payload: lineas } : null];

// Si el controlador falla, la petición recibe un 500 en lugar de quedar colgada.
if (!msg.res) return null;
node.warn(`Error en la API: ${msg.error && msg.error.message}`);
msg.statusCode = 500;
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = { ok: false, error: { codigo: 500, mensaje: 'Error interno del servidor.' } };
return msg;

// Responde al saludo de un cliente nuevo con la instantánea actual (solo a esa sesión).
let datos = msg.payload;
if (typeof datos === 'string') {
    try { datos = JSON.parse(datos); } catch (e) { return null; }
}
if (!datos || datos.tipo !== 'hola') return null;
const nucleo = global.get('simcvi');
const estado = global.get('estado');
if (!nucleo || !estado) return null;
msg.payload = nucleo.instantanea(estado);
return msg;

// Arma la petición POST /api/v2/write con las líneas del ciclo.
const nucleo = global.get('simcvi');
const estado = global.get('estado');
const lineas = Array.isArray(msg.payload) ? msg.payload : [];
if (!nucleo || !estado || !lineas.length) return null;

const url = env.get('INFLUX_URL');
const org = env.get('INFLUX_ORG');
const bucket = env.get('INFLUX_BUCKET');
const token = env.get('INFLUX_TOKEN');
if (!url || !org || !bucket || !token) {
    nucleo.registrarEscritura(estado, { ok: false, error: 'Faltan variables INFLUX_* en el entorno' });
    node.status({ fill: 'grey', shape: 'ring', text: 'sin configuración de InfluxDB' });
    return null;
}

nucleo.registrarEnvio(estado, lineas.length);
return {
    method: 'POST',
    url: `${url}/api/v2/write?org=${encodeURIComponent(org)}&bucket=${encodeURIComponent(bucket)}&precision=ns`,
    headers: {
        Authorization: `Token ${token}`,
        'Content-Type': 'text/plain; charset=utf-8',
        Accept: 'application/json',
    },
    payload: lineas.join('\n'),
    requestTimeout: 5000,
    lineas: lineas.length,
    inicio: Date.now(),
};

// 204 = escritura correcta. En errores de red, statusCode trae el código (p. ej. ECONNREFUSED).
const nucleo = global.get('simcvi');
const estado = global.get('estado');
if (!nucleo || !estado) return null;
const latenciaMs = Date.now() - (msg.inicio || Date.now());
const ok = msg.statusCode === 204;
if (ok) {
    nucleo.registrarEscritura(estado, { ok: true, lineas: msg.lineas, latenciaMs });
    node.status({ fill: 'green', shape: 'dot', text: `${msg.lineas} líneas · ${latenciaMs} ms` });
} else {
    const detalle = String(msg.payload || '').slice(0, 200);
    nucleo.registrarEscritura(estado, { ok: false, latenciaMs, error: `HTTP ${msg.statusCode}: ${detalle}` });
    node.status({ fill: 'red', shape: 'ring', text: `fallo: ${msg.statusCode}` });
}
return null;

// Un mensaje por servicio hacia el mismo nodo HTTP.
const destinos = [
    { servicio: 'influxdb', base: env.get('INFLUX_URL'), ruta: '/health' },
    { servicio: 'grafana', base: env.get('GRAFANA_INTERNAL_URL'), ruta: '/api/health' },
].filter((d) => d.base);
return [destinos.map((d) => ({
    method: 'GET',
    url: d.base + d.ruta,
    servicio: d.servicio,
    requestTimeout: 3000,
    inicio: Date.now(),
    payload: '',
}))];

const nucleo = global.get('simcvi');
const estado = global.get('estado');
if (!nucleo || !estado) return null;
const ok = msg.statusCode === 200;
nucleo.registrarSalud(estado, msg.servicio, {
    ok,
    latenciaMs: Date.now() - msg.inicio,
    detalle: ok ? 'en línea' : `sin respuesta (${msg.statusCode})`,
});
node.status({ fill: ok ? 'green' : 'red', shape: ok ? 'dot' : 'ring', text: `${msg.servicio}: ${ok ? 'ok' : msg.statusCode}` });
// Solo el último chequeo difunde, para no duplicar mensajes.
return msg.servicio === 'grafana' ? { payload: nucleo.instantanea(estado) } : null;
